import numpy as np
import cmath
import scipy.signal as ss
import signal_filter_expected as X

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        if abs(a[i] - ref[i]) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def image():
    img = np.empty((7, 9))
    for i in range(7):
        for j in range(9):
            img[i, j] = float((i * 7 + j * 3) % 11)
    return img

@test
def test_filter_helpers():
    assert close(ss.lfiltic([1.0, 0.5, 0.2], [1.0, -0.3, 0.1], [1.0, 2.0], [0.5, 0.3]), X.lfiltic)
    assert close(ss.lfiltic([0.2, 0.3], [2.0, -0.5, 0.25, 0.1], [1.0]), X.lfiltic2)
    q, r = ss.deconvolve([1.0, 3.0, 5.0, 4.0, 2.0, 1.0], [1.0, 1.0, 0.5])
    assert close(q, X.dec_q) and close(r, X.dec_r)
    img = image()
    assert close(ss.wiener(img), X.wiener)
    assert close(ss.wiener(img, (3, 5), noise=2.0), X.wiener2)
    assert close(ss.wiener(img[0].copy(), 5), X.wiener1d)
    assert close(ss.medfilt2d(img), X.medfilt2d)
    assert close(ss.medfilt2d(img, (3, 5)), X.medfilt2d5)
    assert close(ss.order_filter(img, np.ones((3, 3)), 2), X.ordf)
    assert close(ss.order_filter(img[1].copy(), np.ones(5), 4), X.ordf1d)
    assert close(ss.hilbert2(img), X.hilb2, 1e-9, 1e-12)
    assert close(ss.correlation_lags(7, 4).astype(float), X.lags_f)
    assert close(ss.correlation_lags(7, 4, 'same').astype(float), X.lags_s)
    assert close(ss.correlation_lags(4, 7, 'valid').astype(float), X.lags_v)
    c = [1.0 if ss.choose_conv_method(np.ones(1000), np.ones(500)) == 'fft' else 0.0,
         1.0 if ss.choose_conv_method(np.ones(10), np.ones(5)) == 'fft' else 0.0,
         1.0 if ss.choose_conv_method(np.ones((60, 60)), np.ones((30, 30)), 'same') == 'fft' else 0.0]
    assert close(c, X.ccm)
    s, p = ss.vectorstrength([0.1, 0.35, 1.2, 2.05, 3.3], 1.0)
    assert close([s, p], X.vs)
    s2, p2 = ss.vectorstrength([0.1, 0.35, 1.2, 2.05, 3.3], [0.5, 1.0, 2.5])
    assert close(np.concatenate((s2, p2)), X.vs2)
test_filter_helpers()

@test
def test_waveforms():
    t = np.linspace(-1, 7, 33)
    assert close(ss.sawtooth(t), X.saw)
    assert close(ss.sawtooth(t, 0.3), X.saw2)
    assert close(ss.square(t), X.sq)
    assert close(ss.square(t, 0.2), X.sq2)
    tg = np.linspace(-0.002, 0.002, 21)
    assert close(ss.gausspulse(tg), X.gp)
    assert close([ss.gausspulse('cutoff')], X.gpc)
    yi, yq, ye = ss.gausspulse(tg, fc=2000, retquad=True, retenv=True)
    assert close(yq, X.gpq) and close(ye, X.gpe)
    tc = np.linspace(0, 2, 21)
    assert close(ss.chirp(tc, 1, 2, 5), X.ch_lin)
    assert close(ss.chirp(tc, 1, 2, 5, 'quadratic', phi=30), X.ch_quad)
    assert close(ss.chirp(tc, 1, 2, 5, 'quadratic', vertex_zero=False), X.ch_quad2)
    assert close(ss.chirp(tc, 1, 2, 5, 'logarithmic'), X.ch_log)
    assert close(ss.chirp(tc, 1, 2, 5, 'hyperbolic'), X.ch_hyp)
    assert close(ss.chirp(tc, 1, 2, 5, complex=True), X.ch_c)
    assert close(ss.sweep_poly(tc, [0.5, -1.0, 2.0]), X.swp)
    assert close(ss.unit_impulse(8, 3), X.ui)
    assert close(ss.unit_impulse((3, 4), 'mid'), X.uimid)
test_waveforms()

@test
def test_czt():
    xx = np.empty(20)
    for i in range(20):
        xx[i] = np.cos(0.3 * i) + 0.1 * i
    assert close(ss.czt(xx), X.czt, 1e-9, 1e-11)
    assert close(ss.czt(xx, m=8, w=cmath.exp(-0.2j), a=0.9 * cmath.exp(0.1j)), X.czt2, 1e-9, 1e-11)
    assert close(ss.czt_points(5, 0.9 * cmath.exp(-0.3j), 1.1), X.cztp)
    assert close(ss.zoom_fft(xx, [0.1, 0.4], m=10, fs=2), X.zfft, 1e-9, 1e-11)
    assert close(ss.zoom_fft(xx, 0.5, m=7, endpoint=True), X.zfft2, 1e-9, 1e-11)
test_czt()
